  "insi.evidence.quality.what.can.be.ver": text("Evidence quality — what can be verified row by row", "คุณภาพหลักฐาน — ตรวจสอบได้รายแถวอะไรบ้าง", "证据质量 — 哪些能逐行核实"),
  "insi.top.investments.largest.document": text("Top investments — largest documented projects by value", "การลงทุนสูงสุด — โครงการที่มีเอกสารระบุและมีมูลค่าสูงที่สุด", "最大投资 — 价值最高且有据可查的项目"),
  "insi.what.completed.actually.means.18": text("What \"completed\" actually means — 18 projects self-defined as done", "«เสร็จสมบูรณ์» หมายถึงอะไรจริง ๆ — โครงการ 18 โครงการที่ตัวเองนิยามว่าเสร็จ", "“已完成”真正意味着什么 — 18 个项目自称完成"),
  "insi.what.ascn.measures.and.what.it.d": text("What ASCN measures — and what it doesn't", "สิ่งที่ ASCN วัดผล — และสิ่งที่ไม่วัด", "ASCN 衡量什么 —— 又不衡量什么"),
  "insi.m.e.maturity.vs.peer.networks.7": text("M&E maturity vs peer networks — 7 features, 5 systems", "ความเป็นผู้ใหญ่ของระบบ M&E เมื่อเทียบกับเครือข่ายอื่น — 7 คุณลักษณะ 5 ระบบ", "M&E 成熟度与同类网络对比 — 7 项特征、5 个系统"),
  "insi.imd.smart.city.index.2024.how.as": text("IMD Smart City Index 2024 — how ASEAN cities rank globally", "IMD Smart City Index 2024 — อันดับของเมือง ASEAN ในระดับโลก", "IMD Smart City Index 2024 — 东盟城市在全球的排名"),
  "insi.ascn.in.global.context.beside.in": text("ASCN in global context — beside India, the EU and China", "ASCN ในบริบทระดับโลก — เทียบข้างกับอินเดีย สหภาพยุโรป และจีน", "放在全球看 ASCN — 与印度、欧盟和中国相比"),
  "insi.ascap.2026.2035.alignment.where": text("ASCAP 2026–2035 alignment — where today's portfolio maps to tomorrow's pillars", "การสอดคล้องกับ ASCAP 2026–2035 — โครงการวันนี้ตรงกับเสาหลักของอนาคตตรงไหน", "与 ASCAP 2026–2035 的对应 — 今天的项目组合落在明天的哪根支柱上"),
  "insi.the.delivery.gap.completed.vs.on": text("The delivery gap — completed vs ongoing by focus area, 2025", "ช่องว่างของการส่งมอบ — เสร็จสมบูรณ์เทียบกับอยู่ระหว่างดำเนินการ แยกตามสาขา ปี 2025", "交付缺口 — 2025 年各重点领域的已完成与进行中"),
  "insi.digital.maturity.vs.ascn.activit": text("Digital maturity vs ASCN activity — connectivity, rankings, project volume", "ความเป็นดิจิทัลเทียบกับกิจกรรมของ ASCN — การเชื่อมต่อ อันดับ ปริมาณโครงการ", "数字成熟度与 ASCN 活动 — 连通性、排名、项目数量"),
  "insi.5g.readiness.2024.2030.and.the.v": text("5G readiness 2024 → 2030 — and the vendor geopolitics beneath it", "ความพร้อมรับ 5G ปี 2024 → 2030 — และภูมิรัฐศาสตร์ของผู้จัดหมายที่อยู่เบื้องหลัง", "5G 就绪度 2024 → 2030 —— 以及其下的厂商地缘政治"),
